#include <bits/stdc++.h>
using namespace std;
int main(){
    int N;
    cin >> N;
    for (int tc=1;tc<=N;tc++){
        int H,W;
        cin >> H >> W;
        vector<string> grid(H);
        for (auto &row : grid) cin >> row;
        vector<vector<bool>> visited(H, vector<bool>(W,false));
        map<char,int> cnt;
        int dx[]={-1,1,0,0}, dy[]={0,0,-1,1};
        for (int i=0;i<H;i++) for (int j=0;j<W;j++){
            if (visited[i][j]) continue;
            char c = grid[i][j];
            queue<pair<int,int>> q;
            q.push({i,j});
            visited[i][j]=true;
            while(!q.empty()){
                auto [x,y]=q.front(); q.pop();
                for (int d=0;d<4;d++){
                    int nx=x+dx[d], ny=y+dy[d];
                    if (nx<0||nx>=H||ny<0||ny>=W||visited[nx][ny]) continue;
                    if (grid[nx][ny]!=c) continue;
                    visited[nx][ny]=true;
                    q.push({nx,ny});
                }
            }
            cnt[c]++;
        }
        vector<pair<char,int>> items(cnt.begin(), cnt.end());
        sort(items.begin(), items.end(), [](const pair<char,int>&a, const pair<char,int>&b){
            if (a.second != b.second) return a.second > b.second;
            return a.first < b.first;
        });
        cout << "World #" << tc << "\n";
        for (auto &p : items) cout << p.first << ": " << p.second << "\n";
    }
}

